//! ST-14-2 (static half), AC-48: no type reachable from a method result or a `StatusEvent`
//! is, contains or is named like a token, secret, credential or password.
//!
//! The walk reads the crate's own type definitions (`include_str!` of the source files)
//! and follows every field type from the roots, so a new field or type is covered without
//! registration. Roots come from `ipc_schema::METHODS`, which is generated by the same
//! macro that defines the method enum, so a new method is a new root. A reachable type
//! with no definition in the sources (an external type, `serde_json::Value`) is reported
//! as unresolved and fails the test.

mod common;

use common::source_walk::*;
use ipc_schema::METHODS;

fn replace_once(source: &str, from: &str, to: &str) -> String {
    assert_eq!(
        source.matches(from).count(),
        1,
        "`{from}` must occur once in the real sources"
    );
    source.replacen(from, to, 1)
}

/// The real sources with `edit` applied to the one file that holds `anchor`.
fn sources_with(anchor: &str, replacement: &str) -> Vec<String> {
    TYPE_SOURCES
        .iter()
        .map(|source| {
            if source.contains(anchor) {
                replace_once(source, anchor, replacement)
            } else {
                (*source).to_owned()
            }
        })
        .collect()
}

fn walk_owned(sources: &[String]) -> Walk {
    let refs: Vec<&str> = sources.iter().map(String::as_str).collect();
    walk(&refs, &real_roots())
}

#[test]
fn ac2_no_reachable_type_carries_a_token() {
    let result = walk(&TYPE_SOURCES, &real_roots());

    assert!(
        result.violations.is_empty(),
        "forbidden or unresolved: {:#?}",
        result.violations
    );
    for expected in [
        "DaemonStatus",
        "PairView",
        "HoldView",
        "NodeId",
        "LoginPrompt",
        "StatusEvent",
        "ControlError",
        "SettingsPatch",
    ] {
        assert!(
            result.visited.contains(expected),
            "{expected} not reached; visited {:?}",
            result.visited
        );
    }
}

#[test]
fn ac2_every_method_result_and_params_type_is_a_root() {
    assert_eq!(METHODS.len(), 18);
    let result = walk(&TYPE_SOURCES, &real_roots());

    for method in METHODS {
        for root in idents(&tokenize(method.result))
            .into_iter()
            .chain(idents(&tokenize(method.params)))
        {
            assert!(
                PRIMITIVES.contains(&root.as_str()) || result.visited.contains(&root),
                "{} root {root} not walked",
                method.name
            );
        }
    }
}

#[test]
fn ac2_a_field_named_token_in_a_test_copy_fails() {
    let sources = sources_with(
        "pub account_id: String,",
        "pub account_id: String,\n    pub token: String,",
    );

    let result = walk_owned(&sources);

    assert_eq!(
        result.violations,
        vec!["field AccountView.token".to_owned()]
    );
}

#[test]
fn ac2_a_token_nested_deep_in_a_status_is_found() {
    let sources = sources_with(
        "pub remote_deletes: u32,",
        "pub remote_deletes: u32,\n    pub api_secret: String,",
    );

    let result = walk_owned(&sources);

    assert_eq!(
        result.violations,
        vec!["field HoldView.api_secret".to_owned()]
    );
}

#[test]
fn ac2_a_field_typed_credential_fails() {
    let mut sources = sources_with(
        "pub server_revoked: bool,",
        "pub server_revoked: bool,\n    pub proof: Credential,",
    );
    sources.push("pub struct Credential(pub String);".to_owned());

    let result = walk_owned(&sources);

    assert!(
        result
            .violations
            .iter()
            .any(|v| v.starts_with("type Credential")),
        "{:?}",
        result.violations
    );
}

#[test]
fn ac2_a_token_variant_in_an_enum_fails() {
    let sources = sources_with(
        "Pending,\n    Approved,",
        "Pending,\n    Approved,\n    DeviceToken(String),",
    );

    let result = walk_owned(&sources);

    assert_eq!(
        result.violations,
        vec!["variant LoginState::DeviceToken".to_owned()]
    );
}

#[test]
fn ac2_a_field_of_an_undefined_type_fails() {
    let sources = sources_with(
        "pub server_revoked: bool,",
        "pub server_revoked: bool,\n    pub extra: serde_json::Value,",
    );

    let result = walk_owned(&sources);

    assert!(
        result
            .violations
            .iter()
            .any(|v| v.starts_with("unresolved type Value")),
        "{:?}",
        result.violations
    );
}

#[test]
fn every_reachable_type_has_a_round_trip_case() {
    let exercised = common::round_trip_all();
    let definitions = parse_definitions(&TYPE_SOURCES);
    let result = walk(&TYPE_SOURCES, &real_roots());

    for name in &result.visited {
        let variants = exercised
            .get(name.as_str())
            .unwrap_or_else(|| panic!("no round-trip case for {name}"));
        if definitions[name].is_enum {
            assert_eq!(
                *variants,
                definitions[name].variants.len(),
                "{name}: variants exercised vs defined"
            );
        }
    }
}
